"use strict";

var _constants = require("../../constants.js");
var _helpers = require("../helpers.js");
describe('helpers', () => {
  describe('convertAccessToConstantObject', () => {
    it('disallows access if the access string is undefined', () => {
      const NO_ACCESS_OBJECT = {
        data: _constants.ACCESS_NONE,
        metadata: _constants.ACCESS_NONE
      };
      expect((0, _helpers.convertAccessToConstantObject)()).toEqual(NO_ACCESS_OBJECT);
    });
    it('disallows access if the access string is invalid', () => {
      const NO_ACCESS_OBJECT = {
        data: _constants.ACCESS_NONE,
        metadata: _constants.ACCESS_NONE
      };
      expect((0, _helpers.convertAccessToConstantObject)('invalid-access-string')).toEqual(NO_ACCESS_OBJECT);
    });
    const cases = [['--------', {
      data: _constants.ACCESS_NONE,
      metadata: _constants.ACCESS_NONE
    }], ['r-------', {
      data: _constants.ACCESS_NONE,
      metadata: _constants.ACCESS_VIEW_ONLY
    }], ['r-r-----', {
      data: _constants.ACCESS_VIEW_ONLY,
      metadata: _constants.ACCESS_VIEW_ONLY
    }], ['rw------', {
      data: _constants.ACCESS_NONE,
      metadata: _constants.ACCESS_VIEW_AND_EDIT
    }], ['rwrw----', {
      data: _constants.ACCESS_VIEW_AND_EDIT,
      metadata: _constants.ACCESS_VIEW_AND_EDIT
    }]];
    it.each(cases)('parses the metadata portion of the access string correctly for %s', (accessString, accessConstant) => {
      expect((0, _helpers.convertAccessToConstantObject)(accessString)).toEqual(accessConstant);
    });
  });
  describe('convertConstantObjectToAccess', () => {
    it('returns the default access string if the access constant is not recognised', () => {
      const expected = '--------';
      expect((0, _helpers.convertConstantObjectToAccess)({
        data: 'NOT_RECOGNISED',
        metadata: 'NOT_RECOGNISED'
      })).toEqual(expected);
    });
    const cases = [[{
      data: _constants.ACCESS_NONE,
      metadata: _constants.ACCESS_NONE
    }, '--------'], [{
      data: _constants.ACCESS_NONE,
      metadata: _constants.ACCESS_VIEW_ONLY
    }, 'r-------'], [{
      data: _constants.ACCESS_NONE,
      metadata: _constants.ACCESS_VIEW_AND_EDIT
    }, 'rw------'], [{
      data: _constants.ACCESS_VIEW_ONLY,
      metadata: _constants.ACCESS_NONE
    }, '--r-----'], [{
      data: _constants.ACCESS_VIEW_AND_EDIT,
      metadata: _constants.ACCESS_VIEW_AND_EDIT
    }, 'rwrw----']];
    it.each(cases)('returns the correct metadata access string for %s', (accessConstant, accessString) => {
      expect((0, _helpers.convertConstantObjectToAccess)(accessConstant)).toEqual(accessString);
    });
  });
  describe('isRemovableTarget', () => {
    it('returns false for targets that should not be removable', () => {
      expect((0, _helpers.isRemovableTarget)(_constants.SHARE_TARGET_EXTERNAL)).toBe(false);
      expect((0, _helpers.isRemovableTarget)(_constants.SHARE_TARGET_PUBLIC)).toBe(false);
    });
    it('returns true for all other targets', () => {
      expect((0, _helpers.isRemovableTarget)('Does not exist')).toBe(true);
    });
  });
  describe('isMetadataWriteAccessRemoved', () => {
    const cases = [[false, 'user has ALL authority', {
      currentUser: {
        id: 'currentUSER',
        userGroups: [{
          id: 'userGroup01'
        }],
        authorities: ['ALL']
      },
      type: 'group',
      access: {
        data: _constants.ACCESS_NONE,
        metadata: _constants.ACCESS_NONE
      },
      id: 'userGroup01',
      publicAccess: {
        data: _constants.ACCESS_NONE,
        metadata: _constants.ACCESS_NONE
      },
      users: [],
      groups: [{
        id: 'userGroup01',
        access: {
          data: _constants.ACCESS_VIEW_AND_EDIT,
          metadata: _constants.ACCESS_VIEW_AND_EDIT
        }
      }]
    }], [true, 'user tries to remove their only access via user group', {
      currentUser: {
        id: 'currentUSER',
        userGroups: [{
          id: 'userGroup01'
        }],
        authorities: []
      },
      type: 'group',
      access: {
        data: _constants.ACCESS_NONE,
        metadata: _constants.ACCESS_NONE
      },
      id: 'userGroup01',
      publicAccess: {
        data: _constants.ACCESS_NONE,
        metadata: _constants.ACCESS_NONE
      },
      users: [],
      groups: [{
        id: 'userGroup01',
        access: {
          data: _constants.ACCESS_VIEW_AND_EDIT,
          metadata: _constants.ACCESS_VIEW_AND_EDIT
        }
      }]
    }], [false, 'user updates only data access their only access via user group', {
      currentUser: {
        id: 'currentUSER',
        userGroups: [{
          id: 'userGroup01'
        }],
        authorities: []
      },
      type: 'group',
      access: {
        data: _constants.ACCESS_NONE,
        metadata: _constants.ACCESS_VIEW_AND_EDIT
      },
      id: 'userGroup01',
      publicAccess: {
        data: _constants.ACCESS_NONE,
        metadata: _constants.ACCESS_NONE
      },
      users: [],
      groups: [{
        id: 'userGroup01',
        access: {
          data: _constants.ACCESS_VIEW_AND_EDIT,
          metadata: _constants.ACCESS_VIEW_AND_EDIT
        }
      }]
    }], [false, 'user update groups access but still has access via their user', {
      currentUser: {
        id: 'currentUSER',
        userGroups: [{
          id: 'userGroup01'
        }],
        authorities: []
      },
      type: 'group',
      access: {
        data: _constants.ACCESS_NONE,
        metadata: _constants.ACCESS_NONE
      },
      id: 'userGroup01',
      publicAccess: {
        data: _constants.ACCESS_NONE,
        metadata: _constants.ACCESS_NONE
      },
      users: [{
        id: 'currentUSER',
        access: {
          data: _constants.ACCESS_VIEW_AND_EDIT,
          metadata: _constants.ACCESS_VIEW_AND_EDIT
        }
      }],
      groups: [{
        id: 'userGroup01',
        access: {
          data: _constants.ACCESS_VIEW_AND_EDIT,
          metadata: _constants.ACCESS_VIEW_AND_EDIT
        }
      }]
    }], [false, 'user update groups access but still has access via public access', {
      currentUser: {
        id: 'currentUSER',
        userGroups: [{
          id: 'userGroup01'
        }],
        authorities: []
      },
      type: 'group',
      access: {
        data: _constants.ACCESS_NONE,
        metadata: _constants.ACCESS_VIEW_AND_EDIT
      },
      id: 'userGroup01',
      publicAccess: {
        data: _constants.ACCESS_NONE,
        metadata: _constants.ACCESS_NONE
      },
      users: [],
      groups: [{
        id: 'userGroup01',
        access: {
          data: _constants.ACCESS_VIEW_AND_EDIT,
          metadata: _constants.ACCESS_VIEW_AND_EDIT
        }
      }]
    }], [true, 'user update groups access to give only view access', {
      currentUser: {
        id: 'currentUSER',
        userGroups: [{
          id: 'userGroup01'
        }],
        authorities: []
      },
      type: 'group',
      access: {
        data: _constants.ACCESS_NONE,
        metadata: _constants.ACCESS_VIEW_ONLY
      },
      id: 'userGroup01',
      publicAccess: {
        data: _constants.ACCESS_NONE,
        metadata: _constants.ACCESS_NONE
      },
      users: [],
      groups: [{
        id: 'userGroup01',
        access: {
          data: _constants.ACCESS_VIEW_AND_EDIT,
          metadata: _constants.ACCESS_VIEW_AND_EDIT
        }
      }]
    }], [false, 'user update groups access to give only view access but hass access from another gropu', {
      currentUser: {
        id: 'currentUSER',
        userGroups: [{
          id: 'userGroup01'
        }, {
          id: 'userGroup02'
        }],
        authorities: []
      },
      type: 'group',
      access: {
        data: _constants.ACCESS_NONE,
        metadata: _constants.ACCESS_VIEW_ONLY
      },
      id: 'userGroup01',
      publicAccess: {
        data: _constants.ACCESS_NONE,
        metadata: _constants.ACCESS_NONE
      },
      users: [],
      groups: [{
        id: 'userGroup01',
        access: {
          data: _constants.ACCESS_VIEW_AND_EDIT,
          metadata: _constants.ACCESS_VIEW_AND_EDIT
        }
      }, {
        id: 'userGroup02',
        access: {
          data: _constants.ACCESS_VIEW_AND_EDIT,
          metadata: _constants.ACCESS_VIEW_AND_EDIT
        }
      }]
    }], [false, 'user update user access but has access via group', {
      currentUser: {
        id: 'currentUSER',
        userGroups: [{
          id: 'userGroup01'
        }],
        authorities: []
      },
      type: 'user',
      access: {
        data: _constants.ACCESS_NONE,
        metadata: _constants.ACCESS_VIEW_ONLY
      },
      id: 'currentUSER',
      publicAccess: {
        data: _constants.ACCESS_NONE,
        metadata: _constants.ACCESS_NONE
      },
      users: [{
        id: 'currentUSER',
        access: {
          data: _constants.ACCESS_VIEW_AND_EDIT,
          metadata: _constants.ACCESS_VIEW_AND_EDIT
        }
      }],
      groups: [{
        id: 'userGroup01',
        access: {
          data: _constants.ACCESS_VIEW_AND_EDIT,
          metadata: _constants.ACCESS_VIEW_AND_EDIT
        }
      }]
    }], [true, 'user update user access and has no other access', {
      currentUser: {
        id: 'currentUSER',
        userGroups: [],
        authorities: []
      },
      type: 'user',
      access: {
        data: _constants.ACCESS_NONE,
        metadata: _constants.ACCESS_VIEW_ONLY
      },
      id: 'currentUSER',
      publicAccess: {
        data: _constants.ACCESS_NONE,
        metadata: _constants.ACCESS_NONE
      },
      users: [{
        id: 'currentUSER',
        access: {
          data: _constants.ACCESS_VIEW_AND_EDIT,
          metadata: _constants.ACCESS_VIEW_AND_EDIT
        }
      }],
      groups: []
    }], [false, 'user update public access and access through user', {
      currentUser: {
        id: 'currentUSER',
        userGroups: [],
        authorities: []
      },
      type: 'public',
      access: {
        data: _constants.ACCESS_NONE,
        metadata: _constants.ACCESS_VIEW_ONLY
      },
      publicAccess: {
        data: _constants.ACCESS_NONE,
        metadata: _constants.ACCESS_VIEW_AND_EDIT
      },
      users: [{
        id: 'currentUSER',
        access: {
          data: _constants.ACCESS_VIEW_AND_EDIT,
          metadata: _constants.ACCESS_VIEW_AND_EDIT
        }
      }],
      groups: []
    }], [false, 'user update public access and access through user group', {
      currentUser: {
        id: 'currentUSER',
        userGroups: [{
          id: 'userGroup01'
        }],
        authorities: []
      },
      type: 'public',
      access: {
        data: _constants.ACCESS_NONE,
        metadata: _constants.ACCESS_VIEW_ONLY
      },
      publicAccess: {
        data: _constants.ACCESS_NONE,
        metadata: _constants.ACCESS_VIEW_AND_EDIT
      },
      users: [],
      groups: [{
        id: 'userGroup01',
        access: {
          data: _constants.ACCESS_VIEW_AND_EDIT,
          metadata: _constants.ACCESS_VIEW_AND_EDIT
        }
      }]
    }], [true, 'user update public access and has no other access', {
      currentUser: {
        id: 'currentUSER',
        userGroups: [],
        authorities: []
      },
      type: 'public',
      access: {
        data: _constants.ACCESS_NONE,
        metadata: _constants.ACCESS_VIEW_ONLY
      },
      publicAccess: {
        data: _constants.ACCESS_NONE,
        metadata: _constants.ACCESS_VIEW_AND_EDIT
      },
      users: [],
      groups: []
    }]];
    it.each(cases)('returns %s when %s', (result, _, metadata) => {
      expect((0, _helpers.isMetadataWriteAccessRemoved)(metadata)).toEqual(result);
    });
  });
});